/** Pure parts of the relay service installer: names, generated files, Codex config edits. */

export const LABEL = 'dev.bb.browser-relay';
export const PORT = 8766;
export const MCP_PROXY_VERSION = '0.15.0';
export const MIN_NODE: [number, number] = [20, 19];
export const SERVICE_URL = `http://127.0.0.1:${PORT}/mcp`;
/** Directory names of earlier installs (bb-config chrome-devtools-shared); their LaunchAgents are migrated. */
export const LEGACY_DIR_NAMES = ['chrome-devtools-mcp-shared'];
export const CHROME_FLAGS = ['--autoConnect', '--no-usage-statistics', '--no-performance-crux', '--allow-unrestricted-paths'];

export type Paths = { home: string; installDir: string; plist: string; log: string; codexConfig: string; backupDir: string; prevCodexEntry: string; mcpProxy: string };

export function paths(home: string, codexHome?: string): Paths {
  const installDir = `${home}/.local/share/bb-browser-relay`;
  return {
    home,
    installDir,
    plist: `${home}/Library/LaunchAgents/${LABEL}.plist`,
    log: `${home}/Library/Logs/bb-browser-relay.log`,
    codexConfig: `${codexHome || `${home}/.codex`}/config.toml`,
    backupDir: `${installDir}/backup`,
    prevCodexEntry: `${installDir}/backup/codex-chrome-devtools.previous.toml`,
    mcpProxy: `${home}/.local/bin/mcp-proxy`,
  };
}

const xml = (s: string) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const sh = (s: string) => `'${s.replace(/'/g, `'\\''`)}'`;

export function runScript(p: Paths, nodeBinDir: string): string {
  return [
    '#!/bin/bash',
    '# Browser Relay service (bb-plugin-browser-relay). ONE autoConnect DevTools connection to the',
    '# user\'s main Chrome, served to agents over MCP Streamable HTTP on 127.0.0.1. Chrome 144+ asks',
    '# "Allow remote debugging?" per new connection: one long-lived connection = one Allow per Chrome launch.',
    '# Generated by `bb browser-relay service install`; do not edit in place.',
    `export PATH=${sh(`${nodeBinDir}:/usr/bin:/bin:/usr/sbin:/sbin`)}`,
    `exec ${sh(p.mcpProxy)} --host 127.0.0.1 --port ${PORT} --pass-environment -- \\`,
    `  ${sh(`${p.installDir}/node_modules/.bin/chrome-devtools-mcp`)} \\`,
    `  ${CHROME_FLAGS.join(' ')}`,
    '',
  ].join('\n');
}

export function launchdPlist(p: Paths): string {
  return `<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
  <key>Label</key><string>${LABEL}</string>
  <key>ProgramArguments</key><array><string>${xml(p.installDir)}/run.sh</string></array>
  <key>RunAtLoad</key><true/>
  <key>KeepAlive</key><true/>
  <key>StandardOutPath</key><string>${xml(p.log)}</string>
  <key>StandardErrorPath</key><string>${xml(p.log)}</string>
</dict>
</plist>
`;
}

export const CODEX_TABLE = `[mcp_servers.chrome-devtools]
# Browser Relay: shared single connection to the main Chrome (bb-plugin-browser-relay).
url = "${SERVICE_URL}"
`;

const TABLE_RE = /^\[mcp_servers\.chrome-devtools\][^\n]*\n(?:(?!\[)[^\n]*\n?)*/m;

export function codexEntry(toml: string): string | null {
  return toml.match(TABLE_RE)?.[0] ?? null;
}

export function codexPointsHere(entry: string | null): boolean {
  return !!entry && entry.includes(`url = "${SERVICE_URL}"`);
}

/** Replace only the chrome-devtools table (or append it); everything else stays byte-for-byte. */
export function withCodexEntry(toml: string): string {
  const entry = codexEntry(toml);
  if (entry) return toml.replace(entry, CODEX_TABLE + (entry.endsWith('\n\n') ? '\n' : ''));
  return toml.replace(/\n*$/, '') + (toml.trim() ? '\n\n' : '') + CODEX_TABLE;
}

/** Undo: put back the saved previous entry, or drop the table if there was none. */
export function withoutCodexEntry(toml: string, previous: string): string {
  const entry = codexEntry(toml);
  return entry && codexPointsHere(entry) ? toml.replace(entry, previous) : toml;
}

export function parseNodeVersion(v: string): [number, number] | null {
  const m = v.trim().replace(/^v/, '').match(/^(\d+)\.(\d+)/);
  return m ? [Number(m[1]), Number(m[2])] : null;
}

export function nodeOk(v: [number, number] | null): boolean {
  return !!v && (v[0] > MIN_NODE[0] || (v[0] === MIN_NODE[0] && v[1] >= MIN_NODE[1]));
}

/** A LaunchAgent from an earlier install: runs some `<legacy dir>/run.sh` or our run.sh under another label. */
export function isLegacyAgent(label: string, programArguments: unknown, p: Paths): boolean {
  if (label === LABEL || !Array.isArray(programArguments)) return false;
  return programArguments.some(a => typeof a === 'string' && (a === `${p.installDir}/run.sh` || LEGACY_DIR_NAMES.some(d => a.endsWith(`/${d}/run.sh`))));
}
